/// Called once by `index.js` as it loads: keeps its `OmniError` class for this JS environment, starts the thread that
/// polls the binding's futures, and arranges that the environment's trees are stopped when it goes away (H1).
#[napi]
pub fn setup(env: Env, omni_error: Function<'_, Args, ()>) -> napi::Result<()> {
    exec::start().map_err(|e| napi::Error::from_reason(format!("hugr-omni: cannot start its thread: {e}")))?;
    let owned = Arc::new(Owned::default());
    env.add_env_cleanup_hook(Arc::clone(&owned), |owned| owned.stop_all())?;
    let instance = Instance {
        ctor: omni_error.create_ref()?,
        owned,
    };
    env.set_instance_data(instance, (), |done| release(done.value))

/// The environment's data goes with it. Its `OmniError` reference is let go of, not deleted: the environment is being
/// torn down and frees it itself, and a dying environment may refuse the delete (Bun, with the termination of a Worker
/// pending), which napi-rs would turn into a panic inside a finalizer.
fn release(instance: Instance) {
    let Instance { ctor, owned } = instance;
    std::mem::forget(ctor);
    drop(owned);
}

/// The `OmniError` for `e`, ready to throw or to reject with (it keeps the JS object itself).
pub(crate) fn omni(env: &Env, e: &hugr_omni::Error) -> napi::Error {
    let result = e.result().cloned().map(convert::run_result);
    make(env, e.code().as_str(), e.to_string(), result)
}

/// `INVALID_ARGUMENT` for `field`, whose JS value `value` is not `want` (contract §3: nothing has started).
pub(crate) fn refused(env: &Env, field: &str, value: &Unknown<'_>, want: &str) -> napi::Error {
    let message = format!(
        "INVALID_ARGUMENT: {field} is {}, which index.d.ts does not allow there; pass {want} instead.",
        shown(value)
    );
    make(env, "INVALID_ARGUMENT", message, None)
}

fn make(env: &Env, code: &str, message: String, result: Option<RunResultJs>) -> napi::Error {
    let made = || -> napi::Result<napi::Error> {
        let ctor = &env
            .get_instance_data::<Instance>()?
            .ok_or_else(|| napi::Error::from_reason("hugr-omni: index.js did not call setup()"))?
            .ctor;
        let args = FnArgs::from((code.to_owned(), message, result));
        Ok(napi::Error::from(ctor.borrow_back(env)?.new_instance(args)?))
    };
    made().unwrap_or_else(|failed| failed)

/// A JS value as a message shows it: a string quoted (and cut at 80 characters), a number, `true`, `null`, or its kind.
/// Only primitives are read, so no user code runs.
fn shown(value: &Unknown<'_>) -> String {
    let read = || -> napi::Result<String> {
        Ok(match value.get_type()? {
            ValueType::String => {
                let text = convert::text_of(value).unwrap_or_default();
                match text.char_indices().nth(80) {
                    Some((cut, _)) => format!("{:?}...", &text[..cut]),
                    None => format!("{text:?}"),
                }
            }
            ValueType::Number => value.coerce_to_number()?.get_double()?.to_string(),
            ValueType::Boolean => value.coerce_to_bool()?.to_string(),
            ValueType::Null => "null".to_owned(),
            ValueType::Undefined => "undefined".to_owned(),
            ValueType::Object if value.is_array()? => "an array".to_owned(),
            ValueType::Object => "an object".to_owned(),
            ValueType::Function => "a function".to_owned(),
            ValueType::Symbol => "a symbol".to_owned(),
            ValueType::BigInt => "a bigint".to_owned(),
            _ => "a value of another kind".to_owned(),
        })
    };
    read().unwrap_or_else(|_| "a value that cannot be shown".to_owned())

/// Starts the executor thread (once per process; `setup` calls it when `index.js` loads), so that `spawn` never fails.
pub(crate) fn start() -> std::io::Result<()> {
    static STARTING: Mutex<()> = Mutex::new(());
    let _once = STARTING.lock().unwrap_or_else(PoisonError::into_inner);
    if QUEUE.get().is_none() {
        let (queue, tasks) = mpsc::channel();
        std::thread::Builder::new()
            .name("hugr-omni-node".to_owned())
            .spawn(move || run(tasks))?;
        let _ = QUEUE.set(queue);
    }
    Ok(())

/// A promise settled by `work`: with `to_js` of its value, or with the `OmniError` of its error.
///
/// `work` is polled once right here, on the calling (JS) thread, before the executor thread takes over: what it does
/// at once happens at the call and in call order, as with any JS API (`run()` has started its process when it returns,
/// so a signal aborted after the call cancels a launched run, contract §8).
pub(crate) fn promise<'env, V, D, W>(env: &'env Env, work: W, to_js: fn(V) -> D) -> napi::Result<Object<'env>>
where
    V: Send + 'static,
    D: ToNapiValue + 'static,
    W: Future<Output = Result<V, hugr_omni::Error>> + Send + 'static,
{
    let (deferred, promise) = env.create_deferred::<D, Resolver<D>>()?;
    let mut settle = Settle(Some(deferred));
    let job = async move {
        let done = work.await;
        if let Some(deferred) = settle.0.take() {
            deferred.resolve(Box::new(move |env| match done {
                Ok(value) => Ok(to_js(value)),
                Err(e) => Err(error::omni(&env, &e)),
            }));
        }
    };
    if let Some(task) = Task::new(job) {
        poll(&task);
    }
    Ok(promise)
}

/// A promise that is settled whatever happens to its job: an unsettled `JsDeferred` would hold the event loop forever.
struct Settle<D: ToNapiValue>(Option<JsDeferred<D, Resolver<D>>>);

impl<D: ToNapiValue> Drop for Settle<D> {
    fn drop(&mut self) {
        if let Some(deferred) = self.0.take() {
            deferred.reject(napi::Error::from_reason(
                "hugr-omni: the operation ended without a result",
            ));
        }
    }

/// Polls a task once; a job that is done, or that panicked, is dropped (its promise is then settled by `Settle`).
fn poll(task: &Arc<Task>) {
    let waker = Waker::from(Arc::clone(task));
    let mut slot = task.job.lock().unwrap_or_else(PoisonError::into_inner);
    if let Some(job) = slot.as_mut() {
        let polled = catch_unwind(AssertUnwindSafe(|| job.as_mut().poll(&mut Context::from_waker(&waker))));
        if !matches!(polled, Ok(Poll::Pending)) {
            *slot = None;
        }
    }

/// Runs to completion. An argument refused while it is converted is thrown; `index.js` turns that into a rejection.
#[napi]
pub fn run<'env>(
    env: &'env Env,
    command: Js<'_, String>,
    args: Js<'_, Vec<Js<'_, String>>>,
    options: Option<Js<'_, Object<'_>>>,
    cancel: Option<&Cancel>,
) -> napi::Result<Object<'env>> {
    let (cmd, _) = convert::command(env, command, args, options, cancel)?;
    exec::promise(env, async move { cmd.run().await }, convert::run_result)
}

/// The longest an environment's teardown waits for its trees: a forced stop is one round trip to the supervisor.
const BOUND: Duration = Duration::from_secs(5);

/// The children one JS environment spawned.
#[derive(Default)]
pub(crate) struct Owned(Mutex<Vec<Weak<Kid>>>);

/// The environment is going away: force-stops every tree still held, and returns once they are all gone or
/// `BOUND` has passed. Runs on the JS thread, which is ending; the stops run on the binding's thread.
pub(crate) fn stop_all(&self) {
    let kids: Vec<Arc<Kid>> = lock(&self.0).drain(..).filter_map(|k| k.upgrade()).collect();
    let (done, all_done) = mpsc::channel();
    let count = kids.len();
    for kid in kids {
        let done = done.clone();
        exec::spawn(async move {
            let _ = kid.stop(Some(Duration::ZERO)).await;
            let _ = done.send(());
        });
    }
    let until = Instant::now() + BOUND;
    for _ in 0..count {
        if all_done
            .recv_timeout(until.saturating_duration_since(Instant::now()))
            .is_err()
        {
            return;
        }
    }

